class ValidationError extends Error {
    constructor(public field: string) {
        super(`${field} maydoni noto'g'ri`)
        this.name = "ValidationError"
    }
}

class NotFoundError extends Error {
    constructor(public resource: string) {
        super(`${resource} topilmadi`)
        this.name = "NotFoundError"
    }
}

function process(type: string): string {
    if (type === "validation") throw new ValidationError("email")
    if (type === "notfound") throw new NotFoundError("Foydalanuvchi")
    if (type === "generic") throw new Error("Umumiy xato")
    if (type === "string") throw "oddiy satr otildi"
    return "Muvaffaqiyat"
}

for (const type of ["ok", "validation", "notfound", "generic", "string"]) {
    try {
        console.log(process(type))
    } catch (error) {
        if (error instanceof ValidationError) console.log(`Validatsiya: ${error.field}`)
        else if (error instanceof NotFoundError) console.log(`Topilmadi: ${error.resource}`)
        else if (error instanceof Error) console.log(`Xato: ${error.message}`)
        else console.log(`Noma'lum:`, error)
    }
}

class Connection {
    private open = true

    query(sql: string): string {
        if (!this.open) throw new Error("Ulanish yopilgan")
        if (sql.includes("DROP")) throw new Error("Xavfli so'rov")
        return `Natija: ${sql}`
    }

    close(): void {
        this.open = false
        console.log("  Ulanish yopildi")
    }
}

function runQuery(sql: string): string | null {
    const connection = new Connection()
    try {
        return connection.query(sql)
    } catch (error) {
        console.log("  Xato:", (error as Error).message)
        return null
    } finally {
        connection.close()
    }
}

console.log(runQuery("SELECT * FROM users"))
console.log(runQuery("DROP TABLE users"))

