class AppError extends Error {
    constructor(message: string) {
        super(message)
        this.name = new.target.name     // voris klass nomini oladi
    }
}

class NotFoundError extends AppError {
    constructor(public resource: string, public id: number) {
        super(`${resource} #${id} topilmadi`)
    }
}

class ValidationError extends AppError {
    constructor(public field: string, message: string) {
        super(message)
    }
}

function handle(error: unknown): string {
    if (error instanceof NotFoundError) return "404 — " + error.message
    if (error instanceof ValidationError) return "400 — " + error.field + ": " + error.message
    if (error instanceof Error) return "500 — " + error.message
    return "500 — noma'lum xato"
}

