class ValidationError extends Error {
    constructor(
        public readonly errors: { field: string; message: string }[],
    ) {
        super(`${errors.length} ta validatsiya xatosi`)
        this.name = "ValidationError"
    }

    toJSON(): object {
        return { name: this.name, message: this.message, errors: this.errors }
    }
}

function validate(data: { email?: string; age?: number }): void {
    const errors: { field: string; message: string }[] = []
    if (!data.email?.includes("@")) errors.push({ field: "email", message: "noto'g'ri format" })
    if (data.age === undefined || data.age < 18) errors.push({ field: "age", message: "18 dan katta bo'lishi kerak" })
    if (errors.length > 0) throw new ValidationError(errors)
}

try {
    validate({ email: "notanemail", age: 15 })
} catch (error) {
    if (error instanceof ValidationError) {
        console.log(error.message)
        error.errors.forEach(e => console.log(`  ${e.field}: ${e.message}`))
        console.log(JSON.stringify(error))
    }
}

enum ErrorCode {
    NetworkTimeout = "NETWORK_TIMEOUT",
    InvalidInput = "INVALID_INPUT",
    PermissionDenied = "PERMISSION_DENIED",
}

class AppError extends Error {
    constructor(
        public readonly code: ErrorCode,
        message: string,
        public readonly retryable = false,
    ) {
        super(message)
        this.name = "AppError"
    }
}

const errors = [
    new AppError(ErrorCode.NetworkTimeout, "Server javob bermadi", true),
    new AppError(ErrorCode.InvalidInput, "Email noto'g'ri"),
    new AppError(ErrorCode.PermissionDenied, "Ruxsat yo'q"),
]

for (const error of errors) {
    console.log(`[${error.code}] ${error.message} — ${error.retryable ? "qayta urinish mumkin" : "qayta urinmang"}`)
}

class AppError extends Error {
    constructor(message: string, public readonly userMessage: string) {
        super(message)
        this.name = "AppError"
    }
}

function handleError(error: unknown): { log: string; user: string } {
    if (error instanceof AppError) {
        return { log: `[APP] ${error.message}`, user: error.userMessage }
    }
    if (error instanceof TypeError) {
        return { log: `[TYPE] ${error.message}`, user: "Texnik xato yuz berdi" }
    }
    if (error instanceof Error) {
        return { log: `[ERROR] ${error.message}`, user: "Kutilmagan xato" }
    }
    return { log: `[UNKNOWN] ${String(error)}`, user: "Noma'lum xato" }
}

const testErrors: unknown[] = [
    new AppError("DB connection pool exhausted", "Iltimos, keyinroq urinib ko'ring"),
    new TypeError("Cannot read property 'x' of undefined"),
    new Error("Oddiy xato"),
    "satr",
]

for (const error of testErrors) {
    const { log, user } = handleError(error)
    console.log(`${log}\n  → Foydalanuvchiga: ${user}`)
}

class DatabaseError extends Error {
    constructor(message: string, options?: { cause?: unknown }) {
        super(message, options)
        this.name = "DatabaseError"
    }
}

class ServiceError extends Error {
    constructor(message: string, options?: { cause?: unknown }) {
        super(message, options)
        this.name = "ServiceError"
    }
}

function queryDatabase(): never {
    throw new Error("connection refused")
}

function loadUser(): never {
    try {
        queryDatabase()
    } catch (error) {
        throw new DatabaseError("Foydalanuvchini o'qib bo'lmadi", { cause: error })
    }
}

function handleRequest(): void {
    try {
        loadUser()
    } catch (error) {
        const wrapped = new ServiceError("So'rovni bajarib bo'lmadi", { cause: error })
        let current: Error | undefined = wrapped
        let depth = 0
        while (current) {
            console.log(`${"  ".repeat(depth)}${current.name}: ${current.message}`)
            current = current.cause as Error | undefined
            depth++
        }
    }
}

handleRequest()

