type Result<T, E = string> = { ok: true; value: T } | { ok: false; error: E }

const ok = <T>(value: T): Result<T, never> => ({ ok: true, value })
const err = <E>(error: E): Result<never, E> => ({ ok: false, error })

function parseNumber(input: string): Result<number> {
    const value = Number(input)
    return Number.isNaN(value) ? err(`"${input}" son emas`) : ok(value)
}

function checkPositive(value: number): Result<number> {
    return value > 0 ? ok(value) : err("Musbat son kerak")
}

function sqrt(value: number): Result<number> {
    return ok(Math.sqrt(value))
}

function chain<T, U>(result: Result<T>, fn: (value: T) => Result<U>): Result<U> {
    return result.ok ? fn(result.value) : result
}

for (const input of ["16", "-4", "abc"]) {
    const result = chain(chain(parseNumber(input), checkPositive), sqrt)
    console.log(`"${input}" →`, result.ok ? `√ = ${result.value}` : `Xato: ${result.error}`)
}

