type LoginError = { kind: "not_found" } | { kind: "wrong_password"; attemptsLeft: number } | { kind: "locked"; until: string }
type Result<T, E> = { ok: true; value: T } | { ok: false; error: E }

function login(email: string, password: string): Result<{ token: string }, LoginError> {
    if (email !== "ali@mail.uz") return { ok: false, error: { kind: "not_found" } }
    if (password !== "1234") return { ok: false, error: { kind: "wrong_password", attemptsLeft: 2 } }
    return { ok: true, value: { token: "abc" } }
}

function message(r: Result<{ token: string }, LoginError>) {
    if (r.ok) return "Xush kelibsiz!"
    switch (r.error.kind) {
        case "not_found": return "Bunday foydalanuvchi yo'q"
        case "wrong_password": return `Parol xato. ${r.error.attemptsLeft} ta urinish qoldi`
        case "locked": return `Hisob ${r.error.until} gacha bloklangan`
    }
}

