function parsePercent(s: string): Res<number> {
    if (!s.trim()) return { ok: false, error: { kind: "empty" } }
    const n = Number(s)
    if (Number.isNaN(n)) return { ok: false, error: { kind: "notNumber", input: s } }
    if (n < 0 || n > 100) return { ok: false, error: { kind: "outOfRange", min: 0, max: 100 } }
    return { ok: true, value: n }
}
